package com.ruoyi.metal.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import com.ruoyi.common.core.domain.model.LoginUser;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.metal.security.FactoryScope;import org.springframework.transaction.annotation.*;
class ProductionStockSnapshotTest {
 JdbcTemplate jdbc;FactoryScope scope;long capacity;int sequence;List<Map<String,Object>> candidates;String warehouseStatus;long warehouseFactory;
 @BeforeEach void init(){jdbc=mock(JdbcTemplate.class);scope=mock(FactoryScope.class);capacity=4;sequence=2;warehouseStatus="0";warehouseFactory=1;candidates=List.of(Map.of("id","S1","release_id",7L,"available_quantity",4L),Map.of("id","S2","release_id",8L,"available_quantity",4L));login("metal:warehouse-order:add");when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String q=a.getArgument(0);if(q.contains("metal_warehouse WHERE"))return List.of(Map.of("factory_id",warehouseFactory,"status",warehouseStatus));if(q.contains("sequence_no")&&q.contains("metal_work_order_step"))return List.of(Map.of("sequence_no",sequence));return List.of();});}
 void login(String p){var u=new LoginUser();u.setPermissions(Set.of(p));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 private Object snapshot()throws Exception{try(var mocks=mockConstruction(SemiFlowService.class,(m,c)->{when(m.candidates(1,2,3,4,5)).thenReturn(candidates);when(m.entryCapacity(4,sequence)).thenReturn(capacity);})){var service=new WarehouseService(jdbc,scope);try{return WarehouseService.class.getMethod("productionStockSnapshot",Long.class,Long.class,Long.class,Long.class,Long.class).invoke(service,1L,2L,3L,4L,5L);}catch(java.lang.reflect.InvocationTargetException e){if(e.getCause() instanceof RuntimeException r)throw r;throw e;}}}
 private Map<?,?> context(Object result)throws Exception{return (Map<?,?>)result.getClass().getMethod("entryContext").invoke(result);}
 @Test void multiplePoolsExposeOneSharedCapacity()throws Exception{var result=snapshot();assertEquals(2,((List<?>)result.getClass().getMethod("stocks").invoke(result)).size());var c=context(result);assertEquals("4",c.get("externalEntryCapacity"));assertEquals("1",c.get("factoryId"));assertEquals("2",c.get("warehouseId"));assertEquals("3",c.get("workOrderId"));assertEquals("4",c.get("itemId"));assertEquals("5",c.get("processId"));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void emptyCandidatesStillReturnExplicitZero()throws Exception{candidates=List.of();capacity=0;assertEquals("0",context(snapshot()).get("externalEntryCapacity"));}
 @Test void firstStepHasZeroExternalCapacity()throws Exception{sequence=1;capacity=0;assertEquals("0",context(snapshot()).get("externalEntryCapacity"));}
 @Test void inactiveWarehouseFails(){warehouseStatus="1";assertThrows(ServiceException.class,()->snapshot());}
 @Test void foreignWarehouseFails(){warehouseFactory=99;assertThrows(ServiceException.class,()->snapshot());}
 @Test void unrelatedPermissionFailsBeforeQuery(){login("metal:warehouse:list");assertThrows(ServiceException.class,()->snapshot());verifyNoInteractions(jdbc);}
 @Test void factoryScopeIsEnforced(){doThrow(new ServiceException("跨厂",403)).when(scope).check(1L);assertThrows(ServiceException.class,()->snapshot());verifyNoInteractions(jdbc);}
 @Test void snapshotUsesReadOnlyRepeatableRead()throws Exception{var m=WarehouseService.class.getMethod("productionStockSnapshot",Long.class,Long.class,Long.class,Long.class,Long.class);var tx=m.getAnnotation(Transactional.class);assertNotNull(tx);assertTrue(tx.readOnly());assertEquals(Isolation.REPEATABLE_READ,tx.isolation());}
}
